const KNOWN_FRAMEWORK_SOURCES = [
    'cultureforge:frame:jtbd_first_principle',
    'cultureforge:frame:reverse_engineer_evidence',
    'cultureforge:frame:honest_audit_triad',
    'cultureforge:frame:one_gather_one_release',
    'cultureforge:frame:window_priority',
    'cultureforge:frame:safety_margin',
    'cultureforge:frame:tier1_priority',
    'cultureforge:frame:not_found_is_valid',
    'cultureforge:frame:honest_boundary',
];
// 已知框架名称（用于 source 为 'general_pattern' 时判断）
const KNOWN_FRAMEWORK_NAMES = [
    '一收一放',
    'JTBD第一性原理',
    '逆向工程证据定位',
    '诚实审计三段论',
    '安全边际优先',
    '窗口期优先',
    '诚实边界法则',
    'not_found是合法产出',
    '被广泛归因 ≠ 确实说过',
];
// ================================================================
// 独立置信度评估函数
