/**
 * 判断 mentalModel 的来源类型
 */
function assessSourceType(model) {
    if (!model.source || model.source.trim() === '')
        return 'empty';
    if (KNOWN_FRAMEWORK_SOURCES.includes(model.source))
        return 'known_framework';
    if (KNOWN_FRAMEWORK_NAMES.includes(model.name))
        return 'known_framework';
    // 识别"general_pattern"特征
    if (model.source.startsWith('cultureforge:pattern:'))
        return 'general_pattern';
    // Phase B 框架注入产物：source 以 cultureforge:frame: 开头，是引擎从认知库匹配的候选
    if (model.source.startsWith('cultureforge:frame:'))
        return 'known_framework';
    // 降级路径产物
    if (model.source === 'cultureforge:frame:fallback')
        return 'general_pattern';
    // LLM 自创——不是已知框架也不是已知模式
    return 'llm_invented';
}
/**
 * 判断 mentalModel 的抽象等级
 *
 * concrete = 有具体行为描述或决策场景
 * moderate = 有概念描述但无具体场景
 * abstract = 纯理论表述，与角色脱嵌
 */
function assessAbstractionLevel(model) {
    const appLen = model.application?.length || 0;
    const hasDecisionScenarios = Array.isArray(model.decisionScenarios) && model.decisionScenarios.length > 0;
    if (appLen > 60 || hasDecisionScenarios)
        return 'concrete';
    if (appLen > 20)
        return 'moderate';
    return 'abstract';
}
/**
 * 语义完整性评分
 *
 * 检查 four-part 结构是否完整：
 *   - name (必须有)
 *   - oneLiner (必须>10字符)
 *   - application (必须描述具体场景)
 *   - limitation (必须有)
 *
 * 每个维度 0.25，满分 1.0
 */
function scoreSemanticCompleteness(model) {
    let score = 0;
    // name：必须有
    if (model.name && model.name.trim().length > 0)
        score += 0.25;
    // oneLiner：必须 >10 字符（有实质内容）
    if (model.oneLiner && model.oneLiner.trim().length > 10)
        score += 0.25;
    // application：必须 >20 字符（描述具体场景）
    if (model.application && model.application.trim().length > 20)
        score += 0.25;
    // limitation：必须有
    if (model.limitation && model.limitation.trim().length > 0)
        score += 0.25;
    return Math.min(score, 1.0);
}
/**
 * 计算 mentalModel 的独立置信度
 */
function computeMentalModelConfidence(model) {
    const sourceType = assessSourceType(model);
    const abstractionLevel = assessAbstractionLevel(model);
    const semanticScore = scoreSemanticCompleteness(model);
    // 来源权重
    let sourceScore;
    switch (sourceType) {
        case 'known_framework':
            sourceScore = 0.40;
            break;
        case 'general_pattern':
            sourceScore = 0.25;
            break;
        case 'llm_invented':
            sourceScore = 0.18;
            break; // 从 0.10 提高，避免过于惩罚 LLM 自创但质量尚可的模型
        case 'empty':
            sourceScore = 0.0;
            break;
    }
    // 抽象等级权重
    let abstractionScore;
    switch (abstractionLevel) {
        case 'concrete':
            abstractionScore = 0.35;
            break;
        case 'moderate':
            abstractionScore = 0.20;
            break;
        case 'abstract':
            abstractionScore = 0.05;
            break;
    }
    // 加权融合
    // 权重：来源 40%，语义 35%，抽象 25%
    const independentConfidence = Math.round((sourceScore * 0.40 + semanticScore * 0.35 + abstractionScore * 0.25) * 100) / 100;
    // 异常值钳制
    const clamped = Math.max(0, Math.min(1, independentConfidence));
    const parts = [];
    parts.push(`来源:${sourceType}(${(sourceScore * 100).toFixed(0)}分)`);
    parts.push(`语义:${(semanticScore * 100).toFixed(0)}分`);
    parts.push(`抽象:${abstractionLevel}(${(abstractionScore * 100).toFixed(0)}分)`);
    return {
        sourceType,
        abstractionLevel,
        semanticScore,
        independentConfidence: clamped,
        rationale: parts.join(' | '),
    };
}
